import {footprint,conflicts} from './model.mjs?v=cad18';
import {roomDiagnostics,roomVertices} from './room-pro.mjs?v=cad18';
export const bounds=m=>{const p=footprint(m);return {x0:Math.min(...p.map(p=>p.x)),x1:Math.max(...p.map(p=>p.x)),z0:Math.min(...p.map(p=>p.z)),z1:Math.max(...p.map(p=>p.z))};};
export function smartSnap(m,p,{gap=2,threshold=65,grid=10,exclude=[]}={}){
 const b=bounds(m),candidates={x:[],z:[]},guides=[];
 const add=(axis,delta,label)=>{if(Math.abs(delta)<=threshold)candidates[axis].push({delta,label});};
 for(const other of p.modules){if(other.id===m.id||exclude.includes(other.id)||!other.visible)continue;const o=bounds(other),nearX=Math.max(b.x0,o.x0)-Math.min(b.x1,o.x1)<threshold,nearZ=Math.max(b.z0,o.z0)-Math.min(b.z1,o.z1)<threshold;
 if(m.y<other.y+other.height&&other.y<m.y+m.height){if(nearZ){add('x',o.x1+gap-b.x0,'стык: '+other.name);add('x',o.x0-gap-b.x1,'стык: '+other.name);}if(nearX){add('z',o.z1+gap-b.z0,'стык: '+other.name);add('z',o.z0-gap-b.z1,'стык: '+other.name);}}
 if(nearX)add('z',o.z1-b.z1,'линия фасада');if(nearZ)add('x',o.x0-b.x0,'линия боковины');}
 const v=roomVertices(p.room),area=v.reduce((sum,a,i)=>{const b=v[(i+1)%v.length];return sum+a.x*b.z-b.x*a.z;},0);let angled=null;
 for(let i=0;i<v.length;i++){const a=v[i],q=v[(i+1)%v.length],dx=q.x-a.x,dz=q.z-a.z,len=Math.hypot(dx,dz),nx=-dz/len*Math.sign(area),nz=dx/len*Math.sign(area),along=((m.x-a.x)*dx+(m.z-a.z)*dz)/len;if(along<0||along>len)continue;const dist=Math.min(...footprint(m).map(pt=>(pt.x-a.x)*nx+(pt.z-a.z)*nz)),delta=gap-dist;
 if(Math.abs(delta)<=threshold){if(Math.abs(nx)>.999)add('x',delta*nx,'стена');else if(Math.abs(nz)>.999)add('z',delta*nz,'стена');else if(!angled||Math.abs(delta)<Math.abs(angled.delta))angled={delta,nx,nz};}}
 const result={...m};for(const axis of ['x','z']){candidates[axis].sort((a,b)=>Math.abs(a.delta)-Math.abs(b.delta));const best=candidates[axis][0];if(best){result[axis]=Math.round(m[axis]+best.delta);guides.push(axis.toUpperCase()+': '+best.label);}else result[axis]=Math.round(m[axis]/grid)*grid;}
 if(angled&&!guides.length){result.x=Math.round(m.x+angled.nx*angled.delta);result.z=Math.round(m.z+angled.nz*angled.delta);guides.push('Наклонная стена');}result.x=Math.max(-12000,Math.min(12000,result.x));result.z=Math.max(-12000,Math.min(12000,result.z));return {module:result,guides};
}
export function snapElevation(m,p,threshold=45){if(m.type!=='wall')return m;const candidates=p.modules.filter(o=>o.id!==m.id&&o.type==='wall'&&o.visible&&Math.hypot(o.x-m.x,o.z-m.z)<2500).flatMap(o=>[o.y,o.y+o.height-m.height]).filter(y=>Math.abs(y-m.y)<=threshold).sort((a,b)=>Math.abs(a-m.y)-Math.abs(b-m.y));if(candidates.length)m.y=candidates[0];return m;}
export function canPlace(p,ids){const c=conflicts(p);return !c.outside.some(id=>ids.includes(id))&&!c.overlaps.some(pair=>pair.some(id=>ids.includes(id)))&&!roomDiagnostics(p.room,p.modules.filter(m=>ids.includes(m.id))).some(w=>['outside','obstacle'].includes(w.code));}
export function resizeCoupled(m,axis,value){const old=m[axis],ratio=value/old;m[axis]=value;for(const d of Object.values(m.details||{})){if(d[axis])d[axis]=Math.min(3000,Math.max(2,Math.round(d[axis]*ratio)));const k={width:'x',height:'y',depth:'z'}[axis];if(d[k])d[k]=Math.max(-3000,Math.min(3000,Math.round(d[k]*ratio)));}return m;}
export function alignModules(modules,ids,axis){const list=modules.filter(m=>ids.includes(m.id)&&!m.locked);if(list.length<2)return;const ref=list[0],b=bounds(ref);for(const m of list.slice(1)){if(axis==='top')m.y=Math.max(0,Math.min(2800,ref.y+ref.height-m.height));else if(axis==='bottom')m.y=ref.y;else {const o=bounds(m);if(axis==='front')m.z+=b.z1-o.z1;if(axis==='left')m.x+=b.x0-o.x0;}}}
export function constructionWarnings(p,{maxShelf=900,maxDoor=700}={}){const out=roomDiagnostics(p.room,p.modules);for(const m of p.modules){if(m.visible===false)continue;const span=(m.width-(m.sections+1)*m.thickness)/m.sections;if(m.shelves>0&&span>maxShelf)out.push({code:'shelf',moduleId:m.id,message:`${m.name}: пролёт полки ${Math.round(span)} мм > ${maxShelf}. Нужна проверка нагрузки.`});if(m.doors>0&&m.width/m.doors>maxDoor)out.push({code:'door',moduleId:m.id,message:`${m.name}: ширина фасада превышает выбранный предел ${maxDoor} мм.`});if(m.mechanism==='lift'&&m.height>1200)out.push({code:'mechanism',moduleId:m.id,message:m.name+': высокий подъёмный фасад — проверьте механизм у производителя'});}
return out;}
export function openingWarnings(p){const warnings=[];for(const m of p.modules){if(!m.visible||m.type==='open')continue;const angle=m.rotation*Math.PI/180,fw=Math.min(m.width/(m.doors||1),900),travel=['drawers','dresser'].includes(m.type)?m.depth*.8:fw;for(let step=1;step<=8;step++){const move=travel*step/8,test={...m,width:Math.max(60,m.width-10),depth:60,height:m.height,y:m.y,x:m.x+Math.sin(angle)*(m.depth/2+move),z:m.z+Math.cos(angle)*(m.depth/2+move)};const testProject={...p,modules:p.modules.map(o=>o.id===m.id?test:o)};if(conflicts(testProject).overlaps.some(pair=>pair.includes(m.id))||roomDiagnostics(p.room,[test]).some(w=>['outside','obstacle'].includes(w.code))){warnings.push({code:'opening',moduleId:m.id,message:m.name+': возможное препятствие в зоне открывания (приближённая проверка)'});break;}}}return warnings;}

export const normalizeAngle=angle=>((Math.round(angle)%360)+360)%360;
export function clampGroupTranslation(modules,dx,dz){if(!modules.length)return {dx:0,dz:0};return {dx:Math.max(...modules.map(m=>-12000-m.x),Math.min(dx,...modules.map(m=>12000-m.x))),dz:Math.max(...modules.map(m=>-12000-m.z),Math.min(dz,...modules.map(m=>12000-m.z)))};}
export function validPosition(m){return ['x','z'].every(k=>Number.isFinite(m[k])&&Math.abs(m[k])<=12000)&&Number.isFinite(m.y)&&m.y>=0&&m.y<=2800;}
